# create a symbolic link between two directories and create a blank file on a specific App Server
class symlink {
  file { '/opt/sysops':
    ensure => link,
    target => '/var/www/html',
  }
  file { '/opt/sysops/story.txt':
    ensure => 'present',
    content => '',
  }
}

node 'stapp03.stratos.xfusioncorp.com' {
  include symlink
}

class nginx_installer {
  package { 'nginx':
    ensure => installed,
  }
}

node 'stapp02.stratos.xfusioncorp.com' {
 include nginx_installer
}


# Run 'sudo puppet agent -tv' from server 2

class tomcat_installer {
    package {'tomcat':
        ensure => installed
    }

    service {'tomcat':
        ensure => running,
        enable => true,
    }
}

node 'stapp01.stratos.xfusioncorp.com' 'stapp02.stratos.xfusioncorp.com' 'stapp03.stratos.xfusioncorp.com' {
    include tomcat_installer
}

# Install vim-enhanced and zip packages on the agent node 2 using Puppet
# on node 2 run: 'sudo puppet agent -tv' to apply below class

class multi_package_node {
  package { 'vim-enhanced':
    ensure => installed,
  }
  package { 'zip':
    ensure => installed,
  }
}

node 'stapp02.stratos.xfusioncorp.com' {
  include multi_package_node
}

class data_replacer {
  file_line { 'line_replace':
   path  => '/opt/devops/demo.txt',
   match => 'Welcome to Nautilus Industries!',
   line  => 'Welcome to xFusionCorp Industries!',
  }
}

node 'stapp01.stratos.xfusioncorp.com' {
  include data_replacer
}

class mysql_database {

  # Install the mariadb-server package and start its service
  package { 'mariadb-server':
    ensure => installed,
  }

  service { 'mariadb':
    ensure => running,
    enable => true,
    require => Package['mariadb-server'],
  }

  # Create the database and user with the specified credentials
  mysql::db { 'kodekloud_db3':
    user     => 'kodekloud_cap',
    password => 'dCV3szSGNA',
    host     => 'localhost',
    grant    => ['SELECT', 'UPDATE'],
    require  => Service['mariadb'],
  }
}

node 'stdb01.stratos.xfusioncorp.com' {
    include mysql_database
}

node 'stapp01.stratos.xfusioncorp.com' {
  file { '/opt/security/ecommerce.txt':
    ensure  => 'file',
    content => 'Welcome to xFusionCorp Industries!',
    mode    => '0777',
  }
}

class ntpconfig {
  package { 'ntp':
    ensure => installed,
  }

  file { '/etc/ntp.conf':
    ensure  => file,
    content => "server 1.africa.pool.ntp.org iburst\n",
    require => Package['ntp'],
  }
}

node 'stapp02.stratos.xfusioncorp.com' {
  include ntpconfig
}

$public_key = ''

class ssh_node1 {
  # Configure passwordless SSH connection to App Server 1 (Agent Node 1)
  ssh_authorized_key { 'tony@stapp01':
    ensure => present,
    user   => 'tony',
    type   => 'ssh-rsa',
    key    => $public_key, 
  }
}

class ssh_node2 {
  # Configure passwordless SSH connection to App Server 2 (Agent Node 2)
  ssh_authorized_key { 'steve@stapp02':
    ensure => present,
    user   => 'steve',
    type   => 'ssh-rsa',
    key    => $public_key, 
  }
}

class ssh_node3 {
  # Configure passwordless SSH connection to App Server 3 (Agent Node 3)
  ssh_authorized_key { 'banner@stapp03':
    ensure => present,
    user   => 'banner',
    type   => 'ssh-rsa',
    key    => $public_key, 
  }
}

node stapp01.stratos.xfusioncorp.com {
    include ssh_node1
}

node stapp02.stratos.xfusioncorp.com {
    include ssh_node2
}

node stapp03.stratos.xfusioncorp.com {
    include ssh_node3
}

$public_key = ''

# Define class to use existing key and configure passwordless SSH for App Server 1
class ssh_node1 {
  # Copy SSH key to App Server 1
  ssh_authorized_key { 'tony@stapp01':
    ensure => present,
    user   => 'tony',
    type   => 'ssh-rsa',
    key    => $public_key, 
  }
}

# Define class to use existing key and configure passwordless SSH for App Server 2
class ssh_node2 {
  # Copy SSH key to App Server 2
  ssh_authorized_key { 'steve@stapp02':
    ensure => present,
    user   => 'steve',
    type   => 'ssh-rsa',
    key    => $public_key, 
  }
}

# Define class to use existing key and configure passwordless SSH for App Server 3
class ssh_node3 {
  # Copy SSH key to App Server 3
  ssh_authorized_key { 'banner@stapp03':
    ensure => present,
    user   => 'banner',
    type   => 'ssh-rsa',
    key    => $public_key, 
  }
}

# Include the class for each App Server
node 'stapp01.stratos.xfusioncorp.com' {
  include ssh_node1
}
node 'stapp02.stratos.xfusioncorp.com' {
  include ssh_node2
}
node 'stapp03.stratos.xfusioncorp.com' {
  include ssh_node3
}
